function hqDecode(html) {
  try {
    var m = String(html).match(/APP\.Index\('([A-Za-z0-9_-]+)'\)/);
    if (!m) return null;
    var b64 = m[1].replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    var raw = Packages.android.util.Base64.decode(b64, 2);
    var i;
    for (i = 0; i < raw.length; i++) raw[i] = raw[i] ^ HQ_KEY.charCodeAt(i % HQ_KEY.length);
    var bytes;
    if (raw[0] == 1) {
      var inf = new Packages.java.util.zip.Inflater(true);
      inf.setInput(raw, 1, raw.length - 1);
      var out = new Packages.java.io.ByteArrayOutputStream();
      var buf = Packages.java.lang.reflect.Array.newInstance(Packages.java.lang.Byte.TYPE, 8192);
      var n;
      while (!inf.finished()) {
        n = inf.inflate(buf);
        if (n <= 0) break;
        out.write(buf, 0, n);
      }
      inf.end();
      bytes = out.toByteArray();
    } else {
      bytes = Packages.java.util.Arrays.copyOfRange(raw, 1, raw.length);
    }
    return JSON.parse(String(new Packages.java.lang.String(bytes, 'UTF-8')));
  } catch (e) { return null; }
}
function hqEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function hqStrip(s) {
  return String(s == null ? '' : s).replace(/<[^>]+>/g, '');
}
function hqItems(data) {
  var arr = [];
  if (!data) return arr;
  var lists = [];
  if (data.list) lists.push(data.list);
  if (data.book && data.book.list) lists.push(data.book.list);
  if (data.vod && data.vod.list) lists.push(data.vod.list);
  if (data.new_vod && data.new_vod.list) lists.push(data.new_vod.list);
  if (data.cnxh_list && data.cnxh_list.list) lists.push(data.cnxh_list.list);
  var i, j, it;
  for (i = 0; i < lists.length; i++) {
    for (j = 0; j < lists[i].length; j++) {
      it = lists[i][j];
      if (it.book_id_attr != null) {
        arr.push({ t: 'novel', id: '' + it.book_id_attr, name: it.name || '', pic: it.pic || it.picx || '', author: it.author || '', intro: it.notice || it.content || '', extra: it.tags || '' });
      } else if (it.vod_id != null) {
        arr.push({ t: 'vod', id: '' + it.vod_id, name: it.vod_name || '', pic: it.vod_pic || '', author: it.vod_author || it.user_name || '', intro: it.vod_blurb || '', extra: it.vod_duration || it.vod_remarks || '' });
      }
    }
  }
  return arr;
}
function hqCards(items) {
  var s = '', i, it;
  for (i = 0; i < items.length; i++) {
    it = items[i];
    s += '<div class="hq-item" data-t="' + it.t + '" data-id="' + it.id + '">'
      + '<span class="hq-name">' + hqEsc(it.name) + '</span>'
      + '<img class="hq-pic" src="' + hqEsc(it.pic) + '">'
      + '<span class="hq-author">' + hqEsc(it.author) + '</span>'
      + '<span class="hq-intro">' + hqEsc(String(it.intro).slice(0, 200)) + '</span>'
      + '<span class="hq-extra">' + hqEsc(it.extra) + '</span></div>';
  }
  return s;
}

